<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import TextbookContents from './TextbookContents.vue';
import {textbookNames,textbookEntries,textbookStudyId,compareBookPages,normalizeBookPage,type TextbookKey} from './textbookPages';
import {readBookSelection,type BookSelection} from './textbookReaderState';
import type {ContentsRow} from './textbookContents';
import type {QuestionItem} from './types';
const props=defineProps<{book:TextbookKey;items:QuestionItem[];loading:boolean;error:string}>();
const emit=defineEmits<{book:[key:TextbookKey];open:[selection:BookSelection];retry:[]}>();
const selection=ref(readBookSelection(props.book));
const picked=ref<ContentsRow>();
const pageDialog=ref<HTMLDialogElement>();const pageTrigger=ref<HTMLButtonElement>();const draft=ref('');
watch(()=>props.book,()=>{selection.value=readBookSelection(props.book);picked.value=undefined;});
const ready=computed(()=>new Set(props.items.map(i=>i.id)));
const available=computed(()=>{
 const rows=picked.value?.entries||textbookEntries.filter(e=>e.book===props.book&&e.page===selection.value.from);
 return [...new Set(rows.map(e=>e.page))].sort(compareBookPages).map(page=>({page,count:rows.filter(e=>e.page===page&&ready.value.has(textbookStudyId(e))).length}));
});
function pick(row:ContentsRow){picked.value=row;selection.value={from:row.node.from||row.entries[0]?.page||'',to:row.node.to||'',contentsId:row.node.id,contentsLabel:[...row.path.slice(1),row.node.title].join(' › ')};}
function openPage(page:string){emit('open',{...selection.value,from:page});}
function showPageDialog(){draft.value=selection.value.from;pageDialog.value?.showModal();}
const valid=computed(()=>props.book==='hansol'?/^[1-9]\d*-[1-9]\d*$/.test(normalizeBookPage(draft.value)):/^[1-9]\d*$/.test(normalizeBookPage(draft.value))&&Number(draft.value)<=645);
function applyPage(){if(!valid.value)return;pageDialog.value?.close();emit('open',{from:normalizeBookPage(draft.value),to:'',contentsId:'',contentsLabel:''});}
</script>
<template>
 <section class="textbook-library" aria-label="교재 고르기">
  <header class="library-heading"><div><small>MY TEXTBOOK</small><h1>책을 펼쳐 공부하기</h1><p>목차에서 단원을 고르거나, 수업 중인 쪽을 바로 여세요.</p></div><button ref="pageTrigger" type="button" class="library-page-jump" @click="showPageDialog">쪽번호로 바로 열기 ↗</button></header>
  <div class="library-books" aria-label="교재 선택">
   <button v-for="(name,key) in textbookNames" :key="key" :aria-pressed="book===key" @click="emit('book',key)"><span class="book-spine" :class="key" aria-hidden="true">{{key==='hansol'?'HVAC':'ENERGY'}}</span><span><small>{{key==='hansol'?'공조냉동기계산업기사':'에너지관리산업기사'}}</small><strong>{{name}}</strong><em>{{key==='hansol'?'과목 · 장 · 핵심예상 · 모의고사':'이론 · 기출 · CBT 복원'}}</em></span><b aria-hidden="true">{{book===key?'✓':'→'}}</b></button>
  </div>
  <p v-if="error" role="alert">{{error}} <button @click="emit('retry')">다시 불러오기</button></p>
  <div class="library-desk">
   <div class="library-index"><div class="index-caption"><span>CONTENTS</span><strong>목차</strong></div><TextbookContents :book="book" :items="items" :selected="selection.contentsId" @select="pick" /></div>
   <aside class="library-selection" :class="{'has-picked':!!picked}" aria-label="선택한 교재 범위">
    <small>{{picked?'선택한 단원':'마지막으로 펼친 쪽'}}</small><h2>{{picked?.node.title||`${selection.from}쪽`}}</h2><p v-if="picked" class="selection-path">{{picked.path.join(' / ')}}</p>
    <div class="selection-page-label"><span>PAGE</span><strong>{{selection.from}}<template v-if="selection.to"> — {{selection.to}}</template></strong></div>
    <p v-if="loading" role="status">문제를 불러오는 중…</p>
    <button type="button" class="library-open" :disabled="loading" @click="openPage(selection.from)">{{picked?'이 단원 펼치기':'이어서 펼치기'}} →</button>
    <div v-if="available.length" class="library-page-list"><h3>문제가 있는 쪽</h3><div><button v-for="row in available" :key="row.page" type="button" @click="openPage(row.page)"><strong>{{row.page}}</strong><small>{{row.count?`${row.count}문제`:'연결 확인 중'}}</small></button></div></div>
    <p class="library-note">문제 풀기를 시작하면 메뉴 없는 교재 화면으로 전환됩니다. 답안과 마지막 쪽은 자동 저장됩니다.</p>
   </aside>
  </div>
  <dialog ref="pageDialog" class="library-page-dialog" aria-labelledby="library-page-title" @close="pageTrigger?.focus()" @click="($event.target===pageDialog)&&pageDialog.close()"><form @submit.prevent="applyPage"><header><h2 id="library-page-title">어느 쪽을 펼칠까요?</h2><button type="button" aria-label="쪽 선택 닫기" @click="pageDialog?.close()">×</button></header><p>{{textbookNames[book]}} · 책에 적힌 쪽번호를 입력하세요.</p><label>쪽번호<input v-model="draft" autofocus :placeholder="book==='hansol'?'예: 4-10':'예: 442'" autocomplete="off"></label><small v-if="book==='hansol'">4-10은 범위가 아닌 한 페이지입니다.</small><button type="submit" :disabled="!valid" class="library-open">문제 풀기 →</button></form></dialog>
 </section>
</template>
