@media(max-width:1050px){.library-desk{grid-template-columns:minmax(0,1fr);gap:18px}.library-selection{position:static;grid-row:1}.library-page-list>div{max-height:140px}.library-page-list h3{margin-top:15px}.library-note{margin-top:14px}.library-selection{padding:18px}.selection-page-label{padding:10px 0;margin:12px 0}.library-books strong{font-size:16px}.library-books>button{gap:12px;padding:15px}.book-spine{height:72px;width:48px;flex-basis:48px}.library-books{gap:10px}}
@media(max-width:600px){.library-heading{align-items:start;flex-direction:column;gap:16px;margin-top:8px}.library-heading p{font-size:13px}.library-books{grid-template-columns:1fr}.library-books>button{padding:12px 16px}.book-spine{height:55px;width:40px;flex-basis:40px;font-size:8px}.library-books em{display:none}.library-books strong{margin:5px 0 0;font-size:17px}.library-index{padding:18px 14px}.library-selection h2{font-size:20px}.selection-page-label strong{font-size:20px}.library-heading h1{font-size:27px}.library-page-jump{width:100%}.library-index :deep(.contents-tree){max-height:70dvh}}
@media(max-width:1050px){.library-selection:not(.has-picked){display:grid;grid-template-columns:1fr auto;gap:4px 14px;align-items:center}.library-selection:not(.has-picked)>small{grid-column:1}.library-selection:not(.has-picked) h2{margin:0;grid-column:1;font-size:20px}.library-selection:not(.has-picked)>.library-open{grid-column:2;grid-row:1/3;width:auto;padding:10px 14px;min-height:44px;font-size:13px!important}.library-selection:not(.has-picked) .selection-page-label,.library-selection:not(.has-picked) .library-page-list{display:none}.library-selection:not(.has-picked) .library-note{grid-column:1/-1;font-size:11px;margin-top:8px}}
